import {liftPresentationModel} from './expedition-map.js';
import {floorAddress} from './descent-progress.js';
import {HUD_ART} from './hud-art-registry.js';
import {elementLayoutScale} from './ui-display.js';
export function biomeUnlockView(profile){
 const action=liftPresentationModel(profile).actions.buySeal;if(!action)return null;
 return {...action,enabled:action.enabled&&!profile.run,bestCode:floorAddress(Math.max(1,profile.best)).code,requiredCode:floorAddress(action.requiredFloor).code,nextCode:floorAddress(action.requiredFloor+1).code,floorDone:profile.best>=action.requiredFloor,starsDone:action.earnedStars>=action.requiredStars,percent:Math.min(100,100*action.earnedStars/action.requiredStars)};
}
const markup="<section class=\"bu-window\" aria-label=\"Abrir próximo bioma\">\n  <header class=\"bu-head\"><img class=\"bu-emblem\" alt=\"\"><h2>Próximo bioma</h2><button type=\"button\" class=\"bu-button bu-close cursor-interaction\" aria-label=\"Fechar\">×</button></header>\n  <div class=\"bu-body\"><div class=\"bu-destination\"><h3></h3><span>Libera a primeira parada <b class=\"bu-next-code\"></b></span></div>\n   <div class=\"bu-goals\">\n    <section class=\"bu-goal bu-floor-goal\" aria-label=\"Andar necessário\"><div class=\"bu-goal-top\"><span>Alcançar andar</span><b class=\"bu-floor-check\" aria-hidden=\"true\"></b></div><div class=\"bu-floor-values\"><span class=\"bu-current-floor\"></span><span class=\"bu-arrow\" aria-hidden=\"true\">→</span><strong class=\"bu-required-floor\"></strong></div></section>\n    <section class=\"bu-goal bu-star-goal\" aria-label=\"Estrelas conquistadas na campanha\"><div class=\"bu-goal-top\"><span>Estrelas da campanha</span><b class=\"bu-star-check\" aria-hidden=\"true\"></b></div><div class=\"bu-stars\"><img alt=\"\"><strong></strong></div><div class=\"bu-track\" role=\"progressbar\" aria-label=\"Estrelas conquistadas para abrir o bioma\" aria-valuemin=\"0\"><i></i></div></section>\n   </div>\n   <p class=\"bu-rule\">As estrelas não são gastas.</p>\n  </div>\n  <footer class=\"bu-foot\"><button type=\"button\" class=\"bu-button bu-back cursor-interaction\">‹ Voltar</button><button type=\"button\" class=\"bu-button bu-primary bu-open cursor-interaction\">Abrir bioma</button></footer>\n </section>\n ";
export function mountBiomeUnlock(parent,{profile,onClose,focus=true,softMode=()=>false}={}){
 const doc=parent.ownerDocument,win=doc.defaultView,view=biomeUnlockView(profile);if(!view)return()=>{};
 const host=doc.createElement('section');host.id='gv-biome-next';host.setAttribute('aria-label','Próximo bioma');host.innerHTML=markup;parent.append(host);const q=s=>host.querySelector(s),media=win.matchMedia('(prefers-reduced-motion:reduce)');let disposed=false;
 host.querySelectorAll('img').forEach(e=>e.src=HUD_ART.star.url);q('.bu-close').onclick=onClose;q('.bu-back').id='gvl-overlay-back';q('.bu-open').id='gvl-open-biome';q('.bu-open').dataset.primary='true';
 q('.bu-destination h3').textContent=view.name;q('.bu-next-code').textContent=view.nextCode;q('.bu-current-floor').textContent=view.bestCode;q('.bu-required-floor').textContent=view.requiredCode;q('.bu-floor-goal').dataset.done=String(view.floorDone);q('.bu-star-goal').dataset.done=String(view.starsDone);q('.bu-floor-check').textContent=view.floorDone?'✓':'○';q('.bu-star-check').textContent=view.starsDone?'✓':'○';
 q('.bu-floor-goal').setAttribute('aria-label','Alcançar andar '+view.requiredCode+(view.floorDone?', atingido':', atual '+view.bestCode));q('.bu-stars strong').append(doc.createTextNode(view.earnedStars.toLocaleString('pt-BR')));const denominator=doc.createElement('small');denominator.textContent=' / '+view.requiredStars.toLocaleString('pt-BR');q('.bu-stars strong').append(denominator);q('.bu-star-goal').setAttribute('aria-label','Estrelas da campanha: '+view.earnedStars+' de '+view.requiredStars+(view.starsDone?', atingido':''));
 q('.bu-track').setAttribute('aria-valuemax',view.requiredStars);q('.bu-track').setAttribute('aria-valuenow',Math.min(view.earnedStars,view.requiredStars));q('.bu-track i').style.width=view.percent+'%';q('.bu-open').disabled=!view.enabled;
 function fit(){if(disposed)return;const scale=elementLayoutScale(host)||1,scene=win.getComputedStyle(parent),live=parent.parentElement.querySelector('#gvl-live'),available=(win.innerHeight-24)/scale-(parseFloat(scene.paddingTop)||0)-(parseFloat(scene.paddingBottom)||0)-(live?.offsetHeight||0);q('.bu-window').style.maxHeight=Math.max(180,available)+'px';host.dataset.soft=String(softMode()||media.matches);}
 function key(e){if(e.key!=='Tab')return;const stops=[q('.bu-close'),q('.bu-back'),...(!q('.bu-open').disabled?[q('.bu-open')]:[])],active=host.getRootNode().activeElement,i=stops.indexOf(active);if(i<0||e.shiftKey&&i===0||!e.shiftKey&&i===stops.length-1){e.preventDefault();stops[e.shiftKey?stops.length-1:0].focus({preventScroll:true});}e.stopPropagation();}
 const resize=new win.ResizeObserver(fit);resize.observe(host);host.addEventListener('keydown',key);win.addEventListener('resize',fit);media.addEventListener('change',fit);fit();if(focus)q('.bu-back').focus({preventScroll:true});
 return()=>{if(disposed)return;disposed=true;resize.disconnect();host.removeEventListener('keydown',key);win.removeEventListener('resize',fit);media.removeEventListener('change',fit);host.remove();};
}
